bool PhysicsRayCast::rayCastFirst(const RayCastInput& input, RayCastHit* outHit)
{
    if (!_initialized || _space == nullptr)
        return false;
    if (input.direction.lengthSquared() < 1e-12f)
        return false;
    float maxDist = input.maxDistance > 0.0f ? input.maxDistance : _maxDistance;
    Vec2 dir = input.direction.getNormalized();
    Vec2 end = input.origin + dir * maxDist;
    cpShapeFilter filter = cpShapeFilterNew((cpGroup)(uintptr_t)input.groupFilter,
                                            (cpBitmask)input.categoryMask,
                                            (cpBitmask)input.collisionMask);
    cpSegmentQueryInfo info;
    cpShape* shape = cpSpaceSegmentQueryFirst(_space, PhysicsHelper::point2cpv(input.origin),
                                              PhysicsHelper::point2cpv(end), 0.0f, filter, &info);
    if (shape == nullptr)
        return false;
    if (outHit != nullptr)
    {
        PhysicsShape* physicsShape = static_cast<PhysicsShape*>(cpShapeGetUserData(shape));
        outHit->shape = physicsShape;
        outHit->body = physicsShape != nullptr ? physicsShape->getBody() : nullptr;
        outHit->point = PhysicsHelper::cpv2point(info.point);
        outHit->normal = PhysicsHelper::cpv2point(info.normal);
        outHit->fraction = (float)info.alpha;
        outHit->distance = (float)info.alpha * maxDist;
    }
    return true;
