#include "physics/CCPhysicsRayCast.h"
#if CC_USE_PHYSICS

#include <cmath>
#include <algorithm>
#include "physics/CCPhysicsShape.h"
#include "physics/CCPhysicsBody.h"
#include "physics/CCPhysicsWorld.h"
#include "physics/CCPhysicsHelper.h"

NS_CC_BEGIN

namespace
{
    // Minimum squared length for a vector to be considered non-degenerate.
    const float RAY_EPSILON_SQUARED = 1e-12f;

    // Two Pi, used to spread rays over a full circle.
    const float TWO_PI = 6.28318530717958647692f;

    // PhysicsWorld stores its cpSpace in the protected member _cpSpace and
    // exposes no public accessor, and PhysicsRayCast is not a friend of
    // PhysicsWorld. This helper subclass (which adds no data members, so the
    // object layout is identical) gives access to the underlying chipmunk
    // space so ray casts can be issued through cpSpaceSegmentQuery directly.
    class PhysicsWorldSpaceAccessor : public PhysicsWorld
    {
    public:
        static cpSpace* getSpace(const PhysicsWorld* world)
        {
            return static_cast<const PhysicsWorldSpaceAccessor*>(world)->_cpSpace;
        }
    };

    // Context passed through cpSpaceSegmentQuery's user data pointer.
    struct RayCastQueryContext
    {
        RayCastHit* hits;   // output buffer
        int capacity;       // maximum number of hits the buffer can hold
        int count;          // number of hits recorded so far
        float rayLength;    // length of the query segment, for distance computation
    };

    // Builds a chipmunk shape filter from cocos style category/collision masks
    // and a group value (group 0 means "no group filtering").
    inline cpShapeFilter makeShapeFilter(unsigned int categoryMask, unsigned int collisionMask, int group)
    {
        return cpShapeFilterNew((cpGroup)group, (cpBitmask)categoryMask, (cpBitmask)collisionMask);
    }

    // Fills a RayCastHit from the data reported by a chipmunk segment query.
    inline void fillRayCastHit(cpShape* shape, const cpVect& point, const cpVect& normal,
                               cpFloat alpha, float rayLength, RayCastHit* outHit)
    {
        PhysicsShape* physicsShape = static_cast<PhysicsShape*>(cpShapeGetUserData(shape));
        outHit->shape = physicsShape;
        outHit->body = physicsShape != nullptr ? physicsShape->getBody() : nullptr;
        outHit->point = PhysicsHelper::cpv2point(point);
        outHit->normal = PhysicsHelper::cpv2point(normal);
        outHit->fraction = PhysicsHelper::cpfloat2float(alpha);
        outHit->distance = PhysicsHelper::cpfloat2float(alpha) * rayLength;
    }
}

PhysicsRayCast::PhysicsRayCast()
: _world(nullptr)
, _space(nullptr)
, _defaultCategoryMask(0xFFFFFFFF)
, _defaultCollisionMask(0xFFFFFFFF)
, _defaultGroup(0)
, _maxDistance(10000.0f)
, _initialized(false)
{
}

PhysicsRayCast::~PhysicsRayCast()
{
}

bool PhysicsRayCast::init(PhysicsWorld* world)
{
    if (world == nullptr)
    {
        return false;
    }

    _world = world;
    _space = PhysicsWorldSpaceAccessor::getSpace(world);
    _initialized = (_space != nullptr);
    return _initialized;
}

bool PhysicsRayCast::rayCastFirst(const RayCastInput& input, RayCastHit* outHit)
{
    if (!_initialized || _space == nullptr)
    {
        return false;
    }
    if (input.direction.lengthSquared() < RAY_EPSILON_SQUARED)
    {
        return false;
    }

    float maxDist = input.maxDistance > 0.0f ? input.maxDistance : _maxDistance;
    Vec2 end = input.origin + input.direction.getNormalized() * maxDist;
    cpShapeFilter filter = makeShapeFilter(input.categoryMask, input.collisionMask, input.groupFilter);

    cpSegmentQueryInfo info;
    cpShape* shape = cpSpaceSegmentQueryFirst(_space,
                                              PhysicsHelper::point2cpv(input.origin),
                                              PhysicsHelper::point2cpv(end),
                                              0.0f, filter, &info);
    if (shape == nullptr)
    {
        return false;
    }

    if (outHit != nullptr)
    {
        fillRayCastHit(shape, info.point, info.normal, info.alpha, maxDist, outHit);
    }
    return true;
}

int PhysicsRayCast::rayCastAll(const RayCastInput& input, RayCastHit* outHits, int maxHits)
{
    if (!_initialized || _space == nullptr || outHits == nullptr || maxHits <= 0)
    {
        return 0;
    }
    if (input.direction.lengthSquared() < RAY_EPSILON_SQUARED)
    {
        return 0;
    }

    float maxDist = input.maxDistance > 0.0f ? input.maxDistance : _maxDistance;
    Vec2 end = input.origin + input.direction.getNormalized() * maxDist;
    cpShapeFilter filter = makeShapeFilter(input.categoryMask, input.collisionMask, input.groupFilter);

    RayCastQueryContext context = { outHits, maxHits, 0, maxDist };
    cpSpaceSegmentQuery(_space,
                        PhysicsHelper::point2cpv(input.origin),
                        PhysicsHelper::point2cpv(end),
                        0.0f, filter,
                        &PhysicsRayCast::rayCastAllCallback, &context);

    // chipmunk reports hits in arbitrary order; sort them along the ray.
    std::sort(outHits, outHits + context.count,
              [](const RayCastHit& a, const RayCastHit& b) { return a.fraction < b.fraction; });
    return context.count;
}

bool PhysicsRayCast::rayCastAny(const RayCastInput& input)
{
    RayCastHit hit;
    return rayCastFirst(input, &hit);
}

bool PhysicsRayCast::rayCastClosest(const Vec2& origin, const Vec2& end, RayCastHit* outHit)
{
    if (!_initialized || _space == nullptr)
    {
        return false;
    }

    Vec2 direction = end - origin;
    float length = direction.length();
    if (length * length < RAY_EPSILON_SQUARED)
    {
        return false;
    }

    RayCastInput input = { origin, direction / length, length,
                           _defaultCategoryMask, _defaultCollisionMask, _defaultGroup };
    return rayCastFirst(input, outHit);
}

int PhysicsRayCast::rayCastMultiple(const Vec2& origin, const Vec2& end, RayCastHit* outHits, int maxHits)
{
    if (!_initialized || _space == nullptr || outHits == nullptr || maxHits <= 0)
    {
        return 0;
    }

    Vec2 direction = end - origin;
    float length = direction.length();
    if (length * length < RAY_EPSILON_SQUARED)
    {
        return 0;
    }

    RayCastInput input = { origin, direction / length, length,
                           _defaultCategoryMask, _defaultCollisionMask, _defaultGroup };
    return rayCastAll(input, outHits, maxHits);
}

int PhysicsRayCast::fanRayCast(const Vec2& origin, const Vec2& direction, float angle, int numRays,
                               float maxDistance, RayCastHit* outHits, int maxHits)
{
    if (!_initialized || _space == nullptr || outHits == nullptr || maxHits <= 0 || numRays <= 0)
    {
        return 0;
    }
    if (direction.lengthSquared() < RAY_EPSILON_SQUARED)
    {
        return 0;
    }

    float maxDist = maxDistance > 0.0f ? maxDistance : _maxDistance;
    // Angles are in radians, matching Vec2::getAngle()/Vec2::forAngle().
    float baseAngle = direction.getAngle();
    float startAngle = baseAngle - angle * 0.5f;

    int count = 0;
    for (int i = 0; i < numRays && count < maxHits; ++i)
    {
        float rayAngle = (numRays == 1) ? baseAngle
                                        : startAngle + angle * (float)i / (float)(numRays - 1);
        RayCastInput input = { origin, Vec2::forAngle(rayAngle), maxDist,
                               _defaultCategoryMask, _defaultCollisionMask, _defaultGroup };

        RayCastHit hit;
        if (rayCastFirst(input, &hit))
        {
            outHits[count++] = hit;
        }
    }
    return count;
}

int PhysicsRayCast::circleRayCast(const Vec2& center, float radius, int numRays,
                                  RayCastHit* outHits, int maxHits)
{
    if (!_initialized || _space == nullptr || outHits == nullptr || maxHits <= 0 || numRays <= 0)
    {
        return 0;
    }

    float maxDist = radius > 0.0f ? radius : _maxDistance;

    int count = 0;
    for (int i = 0; i < numRays && count < maxHits; ++i)
    {
        float rayAngle = TWO_PI * (float)i / (float)numRays;
        RayCastInput input = { center, Vec2::forAngle(rayAngle), maxDist,
                               _defaultCategoryMask, _defaultCollisionMask, _defaultGroup };

        RayCastHit hit;
        if (rayCastFirst(input, &hit))
        {
            outHits[count++] = hit;
        }
    }
    return count;
}

bool PhysicsRayCast::lineOfSight(const Vec2& from, const Vec2& to, unsigned int obstacleMask)
{
    if (!_initialized || _space == nullptr)
    {
        return false;
    }

    Vec2 segment = to - from;
    if (segment.lengthSquared() < RAY_EPSILON_SQUARED)
    {
        // Degenerate segment: nothing can block the way.
        return true;
    }

    // Only shapes whose category bits intersect obstacleMask are considered blockers.
    cpShapeFilter filter = cpShapeFilterNew((cpGroup)0, CP_ALL_CATEGORIES, (cpBitmask)obstacleMask);

    cpSegmentQueryInfo info;
    cpShape* shape = cpSpaceSegmentQueryFirst(_space,
                                              PhysicsHelper::point2cpv(from),
                                              PhysicsHelper::point2cpv(to),
                                              0.0f, filter, &info);
    return shape == nullptr;
}

float PhysicsRayCast::distanceToNearestSurface(const Vec2& origin, const Vec2& direction, float maxDist)
{
    if (!_initialized || _space == nullptr)
    {
        return maxDist;
    }
    if (direction.lengthSquared() < RAY_EPSILON_SQUARED)
    {
        return maxDist;
    }

    float dist = maxDist > 0.0f ? maxDist : _maxDistance;
    Vec2 end = origin + direction.getNormalized() * dist;
    cpShapeFilter filter = makeShapeFilter(_defaultCategoryMask, _defaultCollisionMask, _defaultGroup);

    cpSegmentQueryInfo info;
    cpShape* shape = cpSpaceSegmentQueryFirst(_space,
                                              PhysicsHelper::point2cpv(origin),
                                              PhysicsHelper::point2cpv(end),
                                              0.0f, filter, &info);
    if (shape == nullptr)
    {
        // No surface within range: report the full probe distance.
        return dist;
    }
    return PhysicsHelper::cpfloat2float(info.alpha) * dist;
}

void PhysicsRayCast::setDefaultFilter(unsigned int categoryMask, unsigned int collisionMask, int group)
{
    _defaultCategoryMask = categoryMask;
    _defaultCollisionMask = collisionMask;
    _defaultGroup = group;
}

void PhysicsRayCast::setMaxRayCastDistance(float maxDist)
{
    if (maxDist > 0.0f)
    {
        _maxDistance = maxDist;
    }
}

float PhysicsRayCast::computeReflectionAngle(const Vec2& inDirection, const Vec2& normal)
{
    Vec2 reflected = computeReflectionDirection(inDirection, normal);
    if (reflected.lengthSquared() < RAY_EPSILON_SQUARED)
    {
        return 0.0f;
    }
    // Radians, consistent with Vec2::getAngle().
    return reflected.getAngle();
}

Vec2 PhysicsRayCast::computeReflectionDirection(const Vec2& inDirection, const Vec2& normal)
{
    if (inDirection.lengthSquared() < RAY_EPSILON_SQUARED ||
        normal.lengthSquared() < RAY_EPSILON_SQUARED)
    {
        return Vec2::ZERO;
    }

    // r = d - 2 * (d . n) * n, with n normalized; the magnitude of d is preserved.
    Vec2 n = normal.getNormalized();
    float dot = inDirection.dot(n);
    return inDirection - n * (2.0f * dot);
}

Vec2 PhysicsRayCast::computeRefractionDirection(const Vec2& inDirection, const Vec2& normal, float ratio)
{
    if (inDirection.lengthSquared() < RAY_EPSILON_SQUARED ||
        normal.lengthSquared() < RAY_EPSILON_SQUARED)
    {
        return Vec2::ZERO;
    }

    // Snell's law, same formulation as GLSL refract(): the normal must face
    // the incident ray (dot(d, n) < 0); returns Vec2::ZERO on total internal
    // reflection.
    Vec2 d = inDirection.getNormalized();
    Vec2 n = normal.getNormalized();
    float cosI = d.dot(n);
    float k = 1.0f - ratio * ratio * (1.0f - cosI * cosI);
    if (k < 0.0f)
    {
        return Vec2::ZERO;
    }
    return d * ratio - n * (ratio * cosI + std::sqrt(k));
}

void PhysicsRayCast::rayCastAllCallback(cpShape* shape, cpVect point, cpVect normal,
                                        cpFloat alpha, void* data)
{
    RayCastQueryContext* context = static_cast<RayCastQueryContext*>(data);
    if (context == nullptr || shape == nullptr || context->hits == nullptr)
    {
        return;
    }
    if (context->count >= context->capacity)
    {
        // Buffer full: chipmunk has no early-out for segment queries, so just
        // drop any further hits.
        return;
    }

    fillRayCastHit(shape, point, normal, alpha, context->rayLength, &context->hits[context->count]);
    ++context->count;
}

NS_CC_END

#endif // CC_USE_PHYSICS

